using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver — resolves any type.
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// --- 1. GetTypeInfo<T>(): strongly-typed metadata --------------------------
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>  → Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"  Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing -----------------------
// With the default resolver every type resolves, so Person succeeds:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"TryGetTypeInfo<Person>  → found ({info!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<Person>  → not available");

// Build options that use a source-gen context containing ONLY WeatherForecast.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = LimitedContext.Default
};

// WeatherForecast IS in the context → succeeds
if (limited.TryGetTypeInfo<WeatherForecast>(out JsonTypeInfo<WeatherForecast>? wInfo))
    Console.WriteLine($"TryGetTypeInfo<WeatherForecast> (limited) → found ({wInfo!.Type.Name})");
else
    Console.WriteLine("TryGetTypeInfo<WeatherForecast> (limited) → not available");

// Person is NOT in the context → returns false, no exception
if (limited.TryGetTypeInfo<Person>(out _))
    Console.WriteLine("TryGetTypeInfo<Person> (limited) → found");
else
    Console.WriteLine("TryGetTypeInfo<Person> (limited) → not available (expected)");

// --- Types ----------------------------------------------------------------
public record Person(string Name, int Age);

public record WeatherForecast(string City, double TempC);

[JsonSerializable(typeof(WeatherForecast))]
internal partial class LimitedContext : JsonSerializerContext;

